self.onmessage=async({data:m})=>{try{const {outputScale,pcmWav,toPcm16}=await import('./formats.mjs'),{scale,peak}=outputScale(m.channels,m.normalize,m.target);let blob;if(m.format==='wav'){blob=new Blob([pcmWav(m.channels,m.rate,m.bits,scale)],{type:'audio/wav'});}else{importScripts('./vendor/lame.min.js');const encoder=new lamejs.Mp3Encoder(m.channels.length,m.rate,m.bitrate),parts=[],n=m.channels[0].length,frames=m.channels.map(()=>new Int16Array(1152));for(let i=0;i<n;i+=1152){const size=Math.min(1152,n-i),block=m.channels.map((ch,c)=>toPcm16(ch,i,scale,size===1152?frames[c]:frames[c].subarray(0,size)));const packet=encoder.encodeBuffer(...block);if(packet.length)parts.push(new Int8Array(packet));if(i%(1152*100)===0)self.postMessage({progress:i/n});}const tail=encoder.flush();if(tail.length)parts.push(new Int8Array(tail));blob=new Blob(parts,{type:'audio/mpeg'});}self.postMessage({blob,attenuated:peak>1});}catch(e){self.postMessage({error:e.message});}};
